from __future__ import annotations

from typing import Mapping, Optional, Tuple
import heapq


def shortest_path(
    adj: Mapping[str, Mapping[str, int]],
    src: str,
    dst: str,
) -> Optional[Tuple[int, list[str]]]:
    """
    Find the shortest route by road length between two depots.

    ``adj`` is an adjacency map as built by ``build_adjacency`` (directed or not) with
    non-negative km values. Returns ``(total_km, path)`` where ``path`` lists the depot
    codes from ``src`` to ``dst`` inclusive; ``src == dst`` gives ``(0, [src])``.
    Returns None when ``dst`` cannot be reached from ``src``.

    Real networks often contain several routes of equal length; the function must
    always return the same route for the same network, independent of dict insertion
    order.

    Raises KeyError if ``src`` or ``dst`` is not a key of ``adj``.

    Example:
        net = {"A": {"B": 2}, "B": {"A": 2, "C": 3}, "C": {"B": 3}}
        shortest_path(net, "A", "C") == (5, ["A", "B", "C"])
    """
    if src not in adj:
        raise KeyError(f"src {src!r} not in adjacency map")
    if dst not in adj:
        raise KeyError(f"dst {dst!r} not in adjacency map")

    if src == dst:
        return (0, [src])

    # Dijkstra with deterministic tie-breaking.
    # Heap entry: (total_km, num_legs, path_tuple, node)
    # Tie rule: fewer legs wins; then lexicographically smallest path wins.
    heap: list[tuple[int, int, tuple[str, ...], str]] = []
    heapq.heappush(heap, (0, 0, (src,), src))

    # best[v] = (km, legs, path_tuple) for the best known route to v
    best: dict[str, tuple[int, int, tuple[str, ...]]] = {}

    while heap:
        km, legs, path, node = heapq.heappop(heap)

        if node in best:
            bkm, blegs, bpath = best[node]
            if (km, legs, path) >= (bkm, blegs, bpath):
                continue

        best[node] = (km, legs, path)

        if node == dst:
            return (km, list(path))

        for nbr, w in sorted(adj[node].items()):
            new_km = km + w
            new_legs = legs + 1
            new_path = path + (nbr,)
            if nbr not in best:
                heapq.heappush(heap, (new_km, new_legs, new_path, nbr))
            else:
                bkm, blegs, bpath = best[nbr]
                if (new_km, new_legs, new_path) < (bkm, blegs, bpath):
                    heapq.heappush(heap, (new_km, new_legs, new_path, nbr))

    return None
